// ---- Smart 内核专用：Auto/Eco-Auto 组改用 type:smart ----
// Smart 内核的原生智能选路，按目标统计选最优节点，可视为 url-test 的上位替代。
// 验证是否生效：1. 配置能正常加载（官方内核会直接拒绝 type:smart）；
// 2. 代理页点 smart 组内节点可手动固定；3. 日志搜 [Smart] 有 "Connection Group" / "Updated weights"。
function buildSmartBaseOption() {
  const opt = {
    ...groupBaseOption,
    type: 'smart',
    tolerance: 50,
    'exclude-type': 'DIRECT',
    icon: `${iconBaseUrl}Auto.svg`,
    hidden: true,
  };
  // GUI 开关映射
  if (ruleOptionsEnable.Smart启用GBM模型) opt.uselightgbm = true;
  if (ruleOptionsEnable.Smart优先ASN) opt['prefer-asn'] = true;
  if (ruleOptionsEnable.Smart收集训练数据) opt.collectdata = true;
  if (ruleOptionsEnable.Smart低倍率优先) opt['policy-priority'] = '低倍率:1.2'; // 内核要求字符串（名:倍率），写成对象整份配置会被拒
  return opt;
}
const smartBaseOption = buildSmartBaseOption();

